-- Schema initial H2 2.x, avant ajout de la description.
CREATE TABLE utilisateurs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255) NOT NULL, nom VARCHAR(255) NOT NULL, version INTEGER NOT NULL);
CREATE TABLE salles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nom VARCHAR(255) NOT NULL UNIQUE, capacite INTEGER NOT NULL CHECK (capacite > 0), version INTEGER NOT NULL);
CREATE TABLE reservations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, salle_id BIGINT NOT NULL REFERENCES salles(id), utilisateur_id BIGINT NOT NULL REFERENCES utilisateurs(id), dateDebut TIMESTAMP NOT NULL, dateFin TIMESTAMP NOT NULL, version INTEGER NOT NULL, CHECK (dateFin > dateDebut));
CREATE INDEX idx_reservation_creneau ON reservations(salle_id, dateDebut, dateFin);
